"""Patch the files generated by `flutter create` for local_auth + release networking.
Run from the control_center/ folder."""
import pathlib
import re

root = pathlib.Path("android/app")

# 1) MainActivity must extend FlutterFragmentActivity for local_auth
for p in root.rglob("MainActivity.*"):
    s = p.read_text()
    s = s.replace("io.flutter.embedding.android.FlutterActivity", "io.flutter.embedding.android.FlutterFragmentActivity")
    s = re.sub(r"\bFlutterActivity\b", "FlutterFragmentActivity", s)
    p.write_text(s)
    print("patched", p)

# 2) minSdk 23 (local_auth / secure storage)
for name in ("build.gradle.kts", "build.gradle"):
    p = root / name
    if p.exists():
        s = p.read_text()
        s = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 23", s)
        s = re.sub(r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 23", s)
        p.write_text(s)
        print("patched", p)

# 3) Manifest: internet + biometric permissions, app name
m = root / "src/main/AndroidManifest.xml"
s = m.read_text()
perms = (
    '    <uses-permission android:name="android.permission.INTERNET"/>\n'
    '    <uses-permission android:name="android.permission.USE_BIOMETRIC"/>\n'
)
if "android.permission.INTERNET" not in s:
    s = s.replace("<application", perms + "    <application", 1)
s = re.sub(r'android:label="[^"]*"', 'android:label="Control Center"', s, count=1)
m.write_text(s)
print("patched", m)

# 4) App icon (B2B SAS gold ring) — copy prebuilt PNGs into every mipmap density
import shutil
brand = pathlib.Path("branding")
res = root / "src/main/res"
for d in ("mdpi", "hdpi", "xhdpi", "xxhdpi", "xxxhdpi"):
    out = res / f"mipmap-{d}"
    out.mkdir(parents=True, exist_ok=True)
    shutil.copy(brand / f"ic_launcher_{d}.png", out / "ic_launcher.png")
    shutil.copy(brand / f"ic_launcher_round_{d}.png", out / "ic_launcher_round.png")
s = m.read_text()
if "android:roundIcon" not in s:
    s = s.replace('android:icon="@mipmap/ic_launcher"', 'android:icon="@mipmap/ic_launcher"\n        android:roundIcon="@mipmap/ic_launcher_round"', 1)
    m.write_text(s)
print("icons copied")
